import json
from pathlib import Path
p=Path('work/coastal_pipeline/v4/sarasota-bradenton');cat=json.load(open(p/'catalog-input.json'));prices=json.load(open(p/'verified-prices.json'))
modern='https://www.visitsarasota.com/article/then-and-now-architecture-glance-sarasota-county';island='https://annamariaislandchamber.org/wp-content/uploads/AMI26_VisitorsGuidebook_WEB.pdf'
specs={'sarasota':(['#f2eddf','#b7d4cf','#c8d8d9'],['#f7f5e9','#abb9b4'],'flat','glass-bands',modern),'bradenton':(['#dfb88f','#ecd5b5','#d0d8bd'],['#b39780','#b8b4a4'],'flat','stucco',island),'bradenton-beach':(['#f2ccbd','#d7e5ca','#c7e1dc'],['#d3d9d0','#aebeb1'],'gable','porches',island),'cortez':(['#c8bda3','#d8dfc6','#ebe0c4'],['#a9b7ae','#c1c8ba'],'gable','porches',island),'ami':(['#ffd9be','#c9e4d2','#f5e6b1','#d8e7e5'],['#c7d4ce','#e5e6da'],'gable','porches',island),'longboat':(['#f0e2cb','#f7f0df','#bed8d3'],['#cfb39a','#e6e8db'],'flat','balconies',modern),'siesta-key':(['#d9e5ce','#f3ddba','#c6e0dc'],['#d5dcd4','#b3c1b5'],'gable','porches',modern),'venice':(['#f0d6bb','#eac2a8','#f6e7cc'],['#b98268','#c49375'],'gable','stucco',modern),'englewood':(['#d3dbc1','#e9d4ad','#c5d9d0'],['#b7c5bb','#aab7ac'],'gable','porches',modern)}
recipes={id:dict(walls=w,roofs=r,roof=roof,detail=detail,source=source) for id,(w,r,roof,detail,source) in specs.items()}
(p/'editorial.json').write_text(json.dumps({'prices':prices,'recipes':recipes,'manual_fixes':['Anna Maria Island card uses the Anna Maria city median and representative place anchor; it does not claim that median covers Holmes Beach or the entire island.','Districts use mapped town place-label anchors; recipe colors are an editorial interpretation of cited local architectural references.']},indent=2))
